CHAPTER_12_EPIC = {
    'title': 'فصل دوازدهم: تشنج در دخمه و کیمیای نجات',
    'subtitle': 'نفرین جمود دوپامینرژیک بهزاد فروتن، لوودوپا، بی‌پریدن و مهار استاتوس اپی‌لپتیکوس',
    'paragraphs': ['در سردابه\u200cهای تاریک و مرطوب معبد متروکه زیرزمینی، بوی گوگرد، موم عسل، خون تازه و بوی نم\u200cآلود آجرها فضا را پر کرده بود. حسام دانش، شمشیرزن دلیر مقاومت، با چکمه\u200cهای گل\u200cآلود و بازوانی خسته سراسیمه وارد شد. در برابر او، صحنه\u200cای هولناک جریان داشت: بهزاد فروتن در واپسین لحظات فرار از دخمه، با طلسمی سیاه از عصاره قارچ\u200cهای سم\u200cزای استریاتوم و مسدودکننده\u200cهای دوپامین، نفرین «جمود لرزان» را بر تنی چند از شمشیرزنان مقاومت فرو ریخته بود.', 'رزمندگان تنومند ناگهان در جا خشک شده بودند؛ عضلات دست و پایشان مانند چرخ\u200cدنده\u200cهای زنگ\u200cزده (Cogwheel rigidity) در برابر هر حرکتی مقاومت می\u200cکرد، گام\u200cهایشان کوتاه، کند و چسبیده به زمین (Festinating gait) شده بود و انگشتان دست\u200cهایشان با لرزشی مداوم و بی\u200cاختیار شبیه شمردن اسکناس (Pill-rolling tremor) به رعشه افتاده بود. بهزاد از تاریکی زوزه کشیده بود: «دوپامین در عقده\u200cهای قاعده\u200cتان خشکید! استیل\u200cکولین مغزتان را منجمد خواهد کرد!»', 'حسام دانش که اکنون به تسلطی شگرف در فارماکوکینتیک رسیده بود، سستی به خود راه نداد. او کپسول\u200cهای لوودوپا را به همراه کاربی\u200cدوپا (Sinemet) در آب حل کرد و گفت: «دوپامین خالص به دلیل قطبیت مولکولی از سد خونی-مغزی عبور نمی\u200cکند، اما پیش\u200cساز آن یعنی لوودوپا به کمک ناقل اسیدهای آمینه وارد استریاتوم می\u200cشود؛ و کاربی\u200cدوپا آنزیم دکربوکسیلاز محیطی را سد می\u200cکند تا داروی نجات قبل از رسیدن به مغز در خون تباه نشود و تهوع شدید ایجاد نکند!»', 'حسام همزمان برای تسکین سریع لرزش و رژیدیتی، آمپول داروی آنتی\u200cکولینرژیک مرکزی بی\u200cپریدن (Akineton) را به صورت عضلانی تزریق کرد تا طغیان کولینرژیک عقده\u200cها مهار گردد. سپس برای رزمندگانی که در اثر زهر تشنج\u200cزای بهزاد دچار تخلیه\u200cهای الکتریکی مکرر کورتکس مغز و وضعیت تشنجی مداوم (Status Epilepticus) شده بودند، داروهای ضد صرع را به خط کرد: «فاز اول، لورازپام و دیازپام وریدی برای باز کردن کانال\u200cهای کلرید گابا؛ فاز دوم، فسفنی\u200cتوئین وریدی که کانال\u200cهای سدیم وابسته به ولتاژ با شلیک فرکانس بالا را به دام می\u200cاندازد؛ و سدیم والپروات که با مهار گابا-ترانس\u200cآمیناز مهار مغزی را تقویت می\u200cکند!» در عرض ساعتی، جمود عضلات شکسته شد، تشنج\u200cها مهار گشتند و شمشیرزنان با رهایی از قفل حرکتی، بار دیگر تیغ\u200cهای بران خود را در دست فشردند.']
}

CHAPTER_13_EPIC = {
    'title': 'فصل سیزدهم: توکولیتیک‌ها و شتاب زمان',
    'subtitle': 'کرایسیس اکلامپسی در باران آتش؛ منیزیم سولفات، لابتالول و پادزهر کلسیم گلوکونات',
    'paragraphs': ['در زایشگاه سنگر جنوبی، یکی از زنان باردار مبتلا به پره\u200cاکلامپسی شدید ناگهان دچار دوبینی، سردرد ضربان\u200cدار شدید در ناحیه پیشانی، درد شدید اپی\u200cگاستر زیر دنده\u200cهای راست و افزایش ناگهانی فشار خون به ۱۹۰/۱۲۰ میلی\u200cمتر جیوه شد. این علائم هشداردهنده انفجار صرع بارداری یا اکلامپسی قریب\u200cالوقوع بود.', 'زن ناگهان به لرزه افتاد؛ چشمانش سفید شد، فک\u200cهایش بر هم قفل گشت و امواج تشنج ژنرالیزه تونیک-کلونیک تمام پیکرش را به رعشه انداخت؛ زبانش میان دندان\u200cها گیر کرد و کف خون\u200cآلود از دهانش جاری شد. جنین در اثر اسپاسم شریان\u200cهای رحمی دچار دیسترس و برادیکاردی شدید شد.', 'حسام دانش و تهمینه فوراً بر بالین مادر شتافتند. حسام دست تکنسین نادانی را که می\u200cخواست داروی ضد صرع فنی\u200cتوئین یا دیازپام را به عنوان خط اول تزریق کند محکم گرفت و فریاد زد: «در تشنج اکلامپسی بارداری، خط اول ضدصرع\u200cهای سنتی نیستند! داروی انتخابی و طلایی تنها و تنها سولفات منیزیم (MgSO4) است!»', 'حسام پروتکل پرچستور و زوبان را آغاز کرد: چهار گرم سولفات منیزیم وریدی به صورت رقیق در سرم دکستروز طی بیست دقیقه با سرعت انفوزیون شد و ده گرم نیز به صورت عضلانی در دو طرف باسن تزریق گردید. منیزیم با مهار گیرنده\u200cهای گلوتاماترژیک NMDA در قشر کورتکس و مهار ورود کلسیم به پایانه\u200cهای پیش\u200cسیناپسی، تخلیه الکتریکی مغز را مهار کرد و انقباضات سهمگین در دم خاموش شدند.', 'برای مهار فشار خون بحرانی مادر، تهمینه آمپول لابتالول وریدی را با دوز بیست میلی\u200cگرم آهسته تزریق کرد تا افت تدریجی و ایمن فشار خون بدون آسیب به جریان خون جفتی حاصل شود. حسام چکش معاینه را برداشت و رفلکس جهش زانو (Patellar reflex) را بررسی کرد: «رفلکس\u200cهای وتری عمقی (DTR) باید حفظ شوند، تعداد تنفس نباید به زیر دوازده بار در دقیقه سقوط کند، و برون\u200cده ادراری باید بالای سی سی\u200cسی در ساعت بماند! اگر رفلکس\u200cها از بین بروند و تنفس کند شود، مسمومیت مرگبار منیزیم رخ داده است!» او سرنگ ده سی\u200cسی گلوکونات کلسیم ۱۰٪ را بر بالین آماده گذاشت تا هرگونه ایست تنفسی را در نطفه خفه سازد.']
}

